PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE login_data (     id INTEGER PRIMARY KEY AUTOINCREMENT,     email TEXT NOT NULL UNIQUE,     password TEXT NOT NULL,     user_type INTEGER NOT NULL,     last_active DATETIME,     create_date DATETIME DEFAULT CURRENT_TIMESTAMP,     update_date DATETIME );
CREATE TABLE user_profile (     id INTEGER PRIMARY KEY,     username TEXT,     user_type INTEGER NOT NULL,     first_name TEXT,     last_name TEXT,     profile_photo TEXT,     follower_ids TEXT,     following_ids TEXT,     photo_ids TEXT,     favorite_ids TEXT,     interested_ids TEXT,     ticket_ids TEXT,     email TEXT NOT NULL,     password TEXT NOT NULL,     create_date DATETIME DEFAULT CURRENT_TIMESTAMP,     update_date DATETIME, bio_text TEXT, post_ids TEXT,     FOREIGN KEY (id) REFERENCES login_data(id) );
CREATE TABLE venue_profile (     id INTEGER PRIMARY KEY,     username TEXT,     user_type INTEGER NOT NULL,     event_ids TEXT,     title TEXT,     address TEXT,     about TEXT,     status TEXT,     photo_ids TEXT,     email TEXT NOT NULL,     password TEXT NOT NULL,     create_date DATETIME DEFAULT CURRENT_TIMESTAMP,     update_date DATETIME, public_status INTEGER DEFAULT 0, open_hours TEXT DEFAULT 'Mon-Sun: 10AM-10PM', lat_long TEXT,     FOREIGN KEY (id) REFERENCES login_data(id) );
CREATE TABLE events (     id INTEGER PRIMARY KEY AUTOINCREMENT,     venue_id INTEGER NOT NULL,     title TEXT,     time DATETIME,     about TEXT,     create_date DATETIME DEFAULT CURRENT_TIMESTAMP,     update_date DATETIME, photo_id TEXT,     FOREIGN KEY (venue_id) REFERENCES venue_profile(id) );
CREATE TABLE posts (     id INTEGER PRIMARY KEY AUTOINCREMENT,     user_id INTEGER NOT NULL,     post_text TEXT NOT NULL,     photo_id TEXT,     like_ids TEXT DEFAULT '',     create_date DATETIME DEFAULT CURRENT_TIMESTAMP,     update_date DATETIME DEFAULT CURRENT_TIMESTAMP , location_tag VARCHAR(255));
DELETE FROM sqlite_sequence;
CREATE TRIGGER insert_user_profile AFTER INSERT ON login_data WHEN NEW.user_type = 1 BEGIN     INSERT INTO user_profile (         id,         username,         user_type,         email,         password,         create_date     )     VALUES (         NEW.id,         NULL,         NEW.user_type,         NEW.email,         NEW.password,         NEW.create_date     ); END;
CREATE TRIGGER insert_venue_profile AFTER INSERT ON login_data WHEN NEW.user_type = 2 BEGIN     INSERT INTO venue_profile (         id,         username,         user_type,         email,         password,         create_date     )     VALUES (         NEW.id,         NULL,         NEW.user_type,         NEW.email,         NEW.password,         NEW.create_date     ); END;
CREATE TRIGGER delete_user_profile AFTER DELETE ON login_data WHEN OLD.user_type = 1 BEGIN     DELETE FROM user_profile WHERE id = OLD.id; END;
CREATE TRIGGER delete_venue_profile AFTER DELETE ON login_data WHEN OLD.user_type = 2 BEGIN     DELETE FROM venue_profile WHERE id = OLD.id; END;
CREATE TRIGGER add_event_to_venue AFTER INSERT ON events BEGIN UPDATE venue_profile SET event_ids = CASE WHEN event_ids IS NULL OR event_ids = '' THEN CAST(NEW.id AS TEXT) ELSE event_ids || ',' || CAST(NEW.id AS TEXT) END WHERE id = NEW.venue_id; END;
CREATE TRIGGER after_post_insert AFTER INSERT ON posts FOR EACH ROW BEGIN     UPDATE user_profile      SET post_ids = CASE          WHEN post_ids IS NULL OR post_ids = '' THEN CAST(NEW.id AS TEXT)         ELSE post_ids || ',' || CAST(NEW.id AS TEXT)     END      WHERE id = NEW.user_id; END;
CREATE TRIGGER before_post_delete BEFORE DELETE ON posts FOR EACH ROW BEGIN     UPDATE user_profile      SET post_ids = TRIM(',', REPLACE(',' || post_ids || ',', ',' || CAST(OLD.id AS TEXT) || ',', ','))     WHERE id = OLD.user_id; END;
CREATE TRIGGER after_post_update AFTER UPDATE ON posts FOR EACH ROW WHEN NEW.update_date = OLD.update_date BEGIN     UPDATE posts SET update_date = CURRENT_TIMESTAMP WHERE id = NEW.id; END;
